INSERT INTO feature VALUES('pr-holds','workflow','A held pull request, and the stack above it, never lands',NULL,'implemented','ordinary',NULL,'A pull request held on purpose is a draft with its reason commented (`pr:hold`); the owner''s hold is `pr:hold --owner`, or `pr:open --hold` from the opening, which also labels it `hold:owner`, and that label holds it even if the draft is taken back. A pull request in the merge queue, or set to enter it by auto-merge, leaves it before it is drafted. `pr:release` ends either hold. The stacking rule leaves a held pull request out of every stack, and `pr:land`, `pr:watch` and the landing workflow refuse it, and every pull request stacked above it, with one line naming the hold, while the ones below it land.',NULL,'.config/pr-stack/cases.json',NULL,NULL);
